<?php get_header(); ?><main id="primary" class="sd-main"><div class="sd-container sd-content-wrap"><div class="sd-section-heading"><span class="sd-eyebrow"><?php esc_html_e( 'Social Discovery', 'social-discovery' ); ?></span><h1><?php esc_html_e( 'A place to find your people.', 'social-discovery' ); ?></h1><p><?php esc_html_e( 'Discover members, communities, and conversations that make the internet feel a little more human.', 'social-discovery' ); ?></p></div><?php if ( have_posts() ) : ?><div class="sd-grid sd-grid-3"><?php while ( have_posts() ) : the_post(); ?><article class="sd-card sd-card-body"><h2><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h2><p><?php echo esc_html( wp_trim_words( get_the_excerpt(), 24 ) ); ?></p></article><?php endwhile; ?></div><?php the_posts_pagination(); ?><?php else : sd_render_empty( __( 'Nothing here yet', 'social-discovery' ), __( 'Check back soon for new stories and conversations.', 'social-discovery' ) ); endif; ?></div></main><?php get_footer(); ?>
